  "settings.magicPrompts.page.group.githubIssueReview.title": "Revisión de issue",
  "settings.magicPrompts.page.group.githubIssueReview.description": "Prompts usados para el flujo de revisión de issue: mensaje visible del usuario + carga de instrucciones ocultas.",
  "settings.magicPrompts.page.group.githubPrFailedChecksReview.title": "Revisión de PR con checks fallidos",
