  "settings.magicPrompts.page.group.gitConflictResolve.title": "Resolución de conflictos de merge/rebase",
  "settings.magicPrompts.page.group.gitConflictResolve.description": "Prompts usados al resolver conflictos de merge/rebase con IA.",
  "settings.magicPrompts.page.group.gitCherrypickConflictResolve.title": "Resolución de conflictos de cherry-pick",
  "settings.magicPrompts.page.group.gitCherrypickConflictResolve.description": "Prompts usados al resolver conflictos de cherry-pick en el flujo de integración.",
  "settings.magicPrompts.page.group.planImprove.title": "Mejora de plan",
  "settings.magicPrompts.page.group.planImprove.description": "Prompt oculto usado al enviar un plan guardado a un flujo de mejora.",
  "settings.magicPrompts.page.group.planTodo.title": "Planificación de tareas",
  "settings.magicPrompts.page.group.planTodo.description": "Prompt oculto usado al enviar una tarea a una nueva sesión de planificación.",
  "settings.magicPrompts.page.group.planImplement.title": "Implementación de plan",
  "settings.magicPrompts.page.group.planImplement.description": "Prompt oculto usado al enviar un plan guardado a un flujo de implementación.",
  "settings.magicPrompts.page.group.sessionSummary.title": "Resumen de sesión",
  "settings.magicPrompts.page.group.sessionSummary.description": "Prompts usados por el comando /summary: mensaje visible del usuario + instrucciones ocultas. No destructivo: no compacta el historial de la sesión.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "Revisión del espacio de trabajo",
  "settings.magicPrompts.page.group.sessionExplore.title": "Recorrido del código",
  "settings.magicPrompts.page.group.sessionExplore.description": "Prompts usados por el comando /explore: mensaje visible del usuario + instrucciones ocultas. Investiga el repositorio y ofrece una orientación estructurada — la visión general, los módulos principales, cómo se conectan y por dónde empezar — en lugar de un listado archivo por archivo.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Prompts usados por el comando /workspace-review: mensaje visible del usuario + instrucciones ocultas. Revisa el diff del espacio de trabajo: si logra su intención y si es correcto y adecuado, clasificando los hallazgos por severidad.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Planificación de funciones",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Prompts usados por el comando /plan-feature: mensaje visible del usuario + instrucciones ocultas. Ejecuta un diálogo guiado que investiga el código y hace preguntas aclaratorias en lotes pequeños antes de producir un plan de implementación.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "Ponerse al día",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "Prompts usados por el comando /catch-up: mensaje visible del usuario + instrucciones ocultas. Construye contexto según la rama — los commits de la rama, su PR y el trabajo sin confirmar juntos — para entender qué estabas haciendo, y luego da un resumen fácil de digerir y un siguiente paso centrado en el producto.",
  "settings.magicPrompts.page.group.sessionDebug.title": "Depuración",
  "settings.magicPrompts.page.group.sessionDebug.description": "Prompts usados por el comando /debug: mensaje visible del usuario + instrucciones ocultas. Ejecuta una investigación guiada de la causa raíz: captura el síntoma, formula hipótesis, las verifica contra el código y confirma la causa antes de proponer una solución.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "Comparar enfoques",
  "settings.magicPrompts.page.group.sessionWeigh.description": "Prompts usados por el comando /weigh: mensaje visible del usuario + instrucciones ocultas. Investiga el código y luego presenta 2-3 enfoques distintos con sus ventajas y desventajas y una recomendación, sin escribir un plan ni código.",
  "settings.magicPrompts.page.group.sessionFusion.title": "Fusion",
  "settings.magicPrompts.page.group.sessionFusion.description": "Prompts usados para combinar salidas de multi-run en una respuesta final: mensaje visible del usuario + instrucciones ocultas antes de los resultados fuente.",
